'use strict';
function riverAdventure(){state.riverAdventure??={active:false,islands:[],enemies:[],fishing:null,boarding:null};const a=state.riverAdventure;a.islands??=[];a.enemies??=[];const b=state.playerBoat;if(b){b.level??=1;b.hp??=40;b.passengers??=[]}return a}
function riverBoatMax(){return 40+20*((state.playerBoat?.level||1)-1)}
function riverBoatSeats(){return (state.playerBoat?.level||1)===1?0:(state.playerBoat.level-1)*2}
function nearBoatDock(){const b=state.playerBoat;return b&&(!b.aboard&&Math.hypot(b.x-state.p.x,b.y-state.p.y)<2*T||b.aboard&&!!boatLanding())}
function upgradeRiverBoat(){riverAdventure();const b=state.playerBoat;if(!b||b.level>=3||!nearBoatDock())return false;const wood=30*b.level,gold=20*b.level;if(state.wood<wood||state.gold<gold)return false;state.wood-=wood;state.gold-=gold;b.level++;b.hp=riverBoatMax();save();renderRiver(true);return true}
function repairRiverBoat(){riverAdventure();const b=state.playerBoat;if(!b||b.hp>=riverBoatMax()||!nearBoatDock()||state.wood<10)return false;state.wood-=10;b.hp=riverBoatMax();save();renderRiver(true);return true}
function loadRiverPassengers(){riverAdventure();const b=state.playerBoat;if(!b||b.passengers.length>=riverBoatSeats())return false;syncGarrisonActors();const units=state.war.guards.filter(u=>u.hp>0&&u.kind!=='cavalry'&&Math.hypot(u.x-b.x,u.y-b.y)<=3*T).slice(0,riverBoatSeats()-b.passengers.length);if(!units.length)return false;for(const u of units){delete u.order;u.path=[];b.passengers.push(u)}state.war.guards=state.war.guards.filter(u=>!units.includes(u));state.war.soldiers-=units.length;save();renderRiver(true);return true}
function unloadRiverPassengers(){riverAdventure();const b=state.playerBoat;if(!b?.passengers.length)return false;const old=state.p;let spot;try{state.p={x:b.x,y:b.y};spot=boatLanding()}finally{state.p=old}if(!spot)return false;syncGarrisonActors();const home={x:Math.floor(spot.x/T),y:Math.floor(spot.y/T)};for(const u of b.passengers)state.war.guards.push({...u,x:spot.x,y:spot.y,home,path:[],order:null});state.war.soldiers+=b.passengers.length;b.passengers=[];save();renderRiver(true);return true}
const riverAway=kingdomArmyAway;kingdomArmyAway=function(){return riverAway()+(state.playerBoat?.passengers?.length||0)};const riverActors=ownSoldierActors;ownSoldierActors=function(){return [...riverActors(),...(state.playerBoat?.passengers||[])]};
const riverTravel=playerTravelMultiplier;playerTravelMultiplier=function(){return riverTravel()*(state.playerBoat?.aboard?1+.25*((state.playerBoat.level||1)-1):1)};
function toggleRiverFishing(){const a=riverAdventure(),b=state.playerBoat;if(a.fishing){a.fishing=null;save();renderRiver(true);return true}if(!b?.aboard||!personalWater(Math.floor(b.x/T),Math.floor(b.y/T)))return false;a.fishing={x:state.p.x,y:state.p.y,elapsed:0};target=null;save();renderRiver(true);say('Wędka zarzucona. Zostań w miejscu przez 10 sekund gry.');return true}
function safeIsland(x,y){if(y<15||y>N-15)return false;if(Math.hypot(x+.5-state.p.x/T,y+.5-state.p.y/T)<18)return false;for(let dx=-9;dx<=9;dx++)for(let dy=-11;dy<=11;dy++)if(building(x+dx,y+dy)||foreignBuilding(x+dx,y+dy))return false;return !riverAdventure().islands.some(i=>Math.abs(i.y-y)<26)}
function startRiverAdventure(){const a=riverAdventure();if(a.active)return false;const origin=state.settled?.y||Math.floor(state.p.y/T);for(let n=0;n<3;n++){let p=null;for(let k=0;k<90&&!p;k++){const y=Math.floor(origin+[42,92,-55][n]+k*(n===2?-1:1)),x=Math.round(river(y));if(safeIsland(x,y))p={x,y}}if(!p)continue;const id='island-'+n;a.islands.push({...p,id,kind:['ruins','treasure','village'][n],name:['Wyspa Starych Ruin','Wyspa Bursztynu','Opuszczona Przystań'][n],claimed:false});for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++)if(dx*dx+dy*dy<=7)cut.add(tileKey(p.x+dx,p.y+dy));a.enemies.push({id:'raider-'+n,x:(p.x+4.5)*T,y:(p.y+.5)*T,hp:24,maxHp:24,path:[],wait:0,cooldown:0})}if(!a.islands.length){say('Brak bezpiecznego miejsca na wyspy w tej części mapy.');return false}a.active=true;waterRevision++;atlasTerrainSignature='';refreshWater();save();renderRiver(true);say('Wyprawy rzeczne rozpoczęte. Wyspy są oznaczone na mapie świata. Uważaj na czerwone łodzie.');return true}
function claimRiverIsland(id){const a=riverAdventure(),i=a.islands.find(i=>i.id===id);if(!i||i.kind==='fort'||i.claimed||state.playerBoat?.aboard||Math.hypot(state.p.x/T-i.x-.5,state.p.y/T-i.y-.5)>3)return false;i.claimed=true;const reward=i.kind==='ruins'?80:i.kind==='treasure'?120:50;state.gold+=reward;if(i.kind==='village')state.food=Math.min(capacity(),state.food+40);save();renderRiver(true);say('Zbadano: '+i.name+'! +'+reward+' monet'+(i.kind==='village'?' i 40 żywności.':'.'));return true}
function riverWaypoint(id){const i=riverAdventure().islands.find(i=>i.id===id);if(!i)return;state.clock.mapTarget={x:i.x,y:i.y};save();say('Cel na mapie: '+i.name+' · '+i.x+', '+i.y)}
function nearestRiverEnemy(range=5){const b=state.playerBoat;if(!b)return null;return riverAdventure().enemies.filter(e=>e.hp>0&&Math.hypot(e.x-b.x,e.y-b.y)<=range*T).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0]}
function beginRiverBoarding(){const a=riverAdventure(),b=state.playerBoat,e=nearestRiverEnemy(1.6);if(!b?.aboard||b.passengers.length<2||!e||e.hp>e.maxHp/2||state.kingdom.fleet.length+state.kingdom.shipQueue.length>=ownCount('port')*3)return false;a.boarding={id:e.id,elapsed:0};a.fishing=null;target=null;save();renderRiver(true);return true}
const riverEnemyPlans=new Map();
function sinkPersonalRiverBoat(){const b=state.playerBoat;if(!b)return;const lost=b.passengers?.length||0;state.playerBoat=null;const a=riverAdventure();a.fishing=null;a.boarding=null;$('home').onclick();say('Łódka zatonęła. Ludek wrócił do domku. Stracono pasażerów: '+lost+'.');save()}
function updateRiver(dt){const a=riverAdventure(),b=state.playerBoat;
 if(a.fishing){const f=a.fishing;if(!b?.aboard||Math.hypot(state.p.x-f.x,state.p.y-f.y)>.5){a.fishing=null;say('Wędkowanie przerwane przez ruch.')}else{f.elapsed+=dt;if(f.elapsed>=10){f.elapsed%=10;const gain=Math.min(3,Math.max(0,capacity()-state.food));state.food+=gain;say(gain?'Złowiono ryby! +'+gain+' żywności.':'Zapasy żywności są pełne.');save()}}}
 if(b){b.shotClock=Math.max(0,(b.shotClock||0)-dt);for(const u of b.passengers){u.x=b.x;u.y=b.y}}
 for(const e of a.enemies){if(e.hp<=0){riverEnemyPlans.delete(e);continue;}e.cooldown=Math.max(0,e.cooldown-dt);e.wait=Math.max(0,e.wait-dt);const targets=state.buildings.filter(p=>p.type==='port').map(p=>({x:(p.x+.5)*T,y:(p.y+.5)*T,port:p}));if(b?.aboard)targets.push({x:b.x,y:b.y,boat:b});const t=targets.filter(t=>Math.hypot(t.x-e.x,t.y-e.y)<20*T).sort((p,q)=>Math.hypot(p.x-e.x,p.y-e.y)-Math.hypot(q.x-e.x,q.y-e.y))[0];
  for(const tower of state.buildings)if(tower.type==='wieza'&&Math.hypot((tower.x+.5)*T-e.x,(tower.y+.5)*T-e.y)<6*T)e.hp=Math.max(0,e.hp-dt*2);
  for(const ship of state.kingdom.fleet)if(ship.hp>0&&Math.hypot(ship.x-e.x,ship.y-e.y)<6*T)e.hp=Math.max(0,e.hp-dt*2);
  if(t&&e.hp>0){const d=Math.hypot(t.x-e.x,t.y-e.y);if(d<3*T&&e.cooldown<=0){e.cooldown=1.8;if(t.boat)t.boat.hp=Math.max(0,t.boat.hp-3);else damageBuilding(t.port,3);e.shot={x:t.x,y:t.y,time:state.time}}
   if(d>2*T){if(e.path.length){const p=e.path[0],dx=p.x-e.x,dy=p.y-e.y,n=Math.hypot(dx,dy),step=55*dt;if(!personalWater(Math.floor(p.x/T),Math.floor(p.y/T))){e.path=[];e.wait=2}else if(n<=step){e.x=p.x;e.y=p.y;e.path.shift()}else{e.x+=dx/n*step;e.y+=dy/n*step}}else if(e.wait<=0){let plan=riverEnemyPlans.get(e);if(!plan){let goal=t.boat?{x:Math.floor(t.x/T),y:Math.floor(t.y/T)}:portExit(t.port);if(goal){plan=boatRoute({x:Math.floor(e.x/T),y:Math.floor(e.y/T)},goal);riverEnemyPlans.set(e,plan)}}if(plan){const r=plan.next();if(r.done){riverEnemyPlans.delete(e);e.path=r.value||[];e.wait=3}}}}
  }
  if(b?.aboard&&b.combat&&e.hp>0&&Math.hypot(e.x-b.x,e.y-b.y)<=5*T){if(b.shotClock<=0){b.shotClock=1.5;e.hp=Math.max(0,e.hp-(2+b.passengers.length));b.shot={x:e.x,y:e.y,time:state.time}}}
  if(e.hp<=0&&!e.rewarded){e.rewarded=true;state.gold+=25;save();say('Pokonano rzecznych najeźdźców! +25 monet.')}
 }
 if(a.boarding){const e=a.enemies.find(e=>e.id===a.boarding.id);if(!b?.aboard||b.passengers.length<2||!e||e.hp<=0||e.hp>e.maxHp/2||Math.hypot(e.x-b.x,e.y-b.y)>1.6*T){a.boarding=null}else{a.boarding.elapsed+=dt;if(a.boarding.elapsed>=6){if(state.kingdom.fleet.length+state.kingdom.shipQueue.length<ownCount('port')*3){e.hp=0;e.rewarded=true;state.kingdom.fleet.push({id:'captured-'+state.kingdom.nextId++,x:e.x,y:e.y,hp:30,passengers:[],cooldown:0});say('Abordaż udany! Zdobyty statek jest w panelu Królestwo → Flota.')}a.boarding=null;save()}}}
 if(b&&b.hp<=0)sinkPersonalRiverBoat();renderRiver();
}
const riverStep=simulationStep;simulationStep=function(dt){riverStep(dt);updateRiver(dt)};
const riverPomost=['pomost','⚓','Pomost',10,0,'Cumowanie i zejście na wodę. Łącz kolejne odcinki od brzegu.'];defs.push(riverPomost);const pierButton=document.createElement('button');pierButton.textContent='⚓ Pomost · 10 drewna';pierButton.onclick=()=>setMode('pomost');$('buildings').append(pierButton);
function drawPier(b,x,y){const cy=y-5,connected=(dx,dy)=>building(b.x+dx,b.y+dy)?.type==='pomost',north=connected(0,-1),south=connected(0,1),west=connected(-1,0),east=connected(1,0);artRect(x-24,cy-24,48,48,'#765735');for(let i=-23;i<24;i+=6)artRect(x+i,cy-24,4,48,'#bb9861');if(!north)artRect(x-24,cy-24,48,3,'#84613d');if(!south)artRect(x-24,cy+21,48,3,'#84613d');if(!west)artRect(x-24,cy-24,2,48,'#6b4f33');if(!east)artRect(x+22,cy-24,2,48,'#6b4f33');for(const [dx,dy,outer] of [[-20,-20,!west&&!north],[20,-20,!east&&!north],[-20,20,!west&&!south],[20,20,!east&&!south]])if(outer){artRect(x+dx-2,cy+dy-8,4,12,'#6f5336');artRect(x+dx-3,cy+dy-10,6,4,'#d3b781')}}
const riverStructure=structure;structure=function(b,x,y){if(b.type!=='pomost'){riverStructure(b,x,y);return}drawPier(b,x,y)};
const riverWorld=drawWarWorld;drawWarWorld=function(){riverWorld();const a=riverAdventure(),b=state.playerBoat;for(const i of a.islands)if(i.kind!=='fort'&&seen.has(tileKey(i.x,i.y))){const x=(i.x+.5)*T,y=(i.y+.5)*T;if(i.kind==='village')structure({x:i.x,y:i.y,type:'dom'},x,y);else if(i.kind==='ruins')structure({type:'ruiny'},x,y);else{artRect(x-10,y-8,20,14,'#946638');artRect(x-10,y-9,20,4,'#d5b369');artRect(x-2,y-5,4,6,'#eed888')}ctx.font='11px system-ui';const label=(i.claimed?'✓ ':'◆ ')+i.name;artRect(x-55,y-52,ctx.measureText(label).width+10,17,'#20392ed9');ctx.fillStyle='#f0ddb0';ctx.fillText(label,x-50,y-40)}for(const e of a.enemies)if(e.hp>0&&seen.has(tileKey(Math.floor(e.x/T),Math.floor(e.y/T)))){drawWarship(e,true);artRect(e.x-20,e.y-67,40,4,'#563f34');artRect(e.x-20,e.y-67,40*e.hp/e.maxHp,4,'#da795e');ctx.fillStyle='#f0c9a4';ctx.font='10px system-ui';ctx.fillText('NAJEŹDŹCY',e.x-30,e.y-73);if(e.shot&&state.time-e.shot.time<.25)artLine([[e.x,e.y-25],[e.shot.x,e.shot.y-10]],'#e2bd7a',2)}if(b?.aboard){for(let i=0;i<b.passengers.length;i++){const dx=(i%2?1:-1)*12,dy=i<2?6:17;artRect(b.x+dx-3,b.y+dy-8,6,8,'#7395a7');ctx.fillStyle='#e6c897';ctx.beginPath();ctx.arc(b.x+dx,b.y+dy-12,3,0,7);ctx.fill()}if(b.shot&&state.time-b.shot.time<.25)artLine([[b.x,b.y-10],[b.shot.x,b.shot.y-15]],'#dce4c7',2);if(a.fishing){artLine([[b.x+6,b.y-10],[b.x+23,b.y-35],[b.x+31,b.y+10]],'#d1bd8f');ctx.fillStyle='#edce83';ctx.font='11px system-ui';ctx.fillText('Ryby · '+Math.ceil(10-a.fishing.elapsed)+' s',b.x-30,b.y-38)}}};
const riverAtlas=atlasEntities;atlasEntities=function(){const a=riverAdventure();return [...riverAtlas(),...a.islands.map(i=>({id:i.id,type:'island',label:(i.claimed?'✓ ':'◆ ')+i.name,x:i.x+.5,y:i.y+.5,color:'#e4cf81',route:[]})),...a.enemies.filter(e=>e.hp>0&&seen.has(tileKey(Math.floor(e.x/T),Math.floor(e.y/T)))).map(e=>({id:e.id,type:'ship',label:'Rzeczni najeźdźcy',x:e.x/T,y:e.y/T,color:'#d9795e',route:[]}))]};
const riverPanel=document.createElement('aside');riverPanel.id='riverPanel';riverPanel.className='war-panel hidden';riverPanel.innerHTML='<div class="war-title"><h2>Łódka i rzeczne wyprawy</h2><button id="riverClose">✕</button></div><div id="riverStatus"></div><div id="riverContent"></div>';document.body.append(riverPanel);const riverOpen=document.createElement('button');riverOpen.textContent='🛶 Wyprawy rzeczne';riverOpen.onclick=()=>{$('riverPanel').classList.remove('hidden');renderRiver(true)};$('clockControls').append(riverOpen);$('riverClose').onclick=()=>$('riverPanel').classList.add('hidden');
let riverPanelSignature='';function renderRiver(force=false){if($('riverPanel').classList.contains('hidden'))return;const a=riverAdventure(),b=state.playerBoat;$('riverStatus').textContent=b?'Łódka: poziom '+b.level+'/3 · '+Math.ceil(b.hp)+'/'+riverBoatMax()+' PŻ · pasażerowie '+b.passengers.length+'/'+riverBoatSeats()+(a.fishing?' · Ryby za '+Math.ceil(10-a.fishing.elapsed)+' s':'')+(a.boarding?' · Abordaż za '+Math.ceil(6-a.boarding.elapsed)+' s':''):'Najpierw zbuduj swoją łódkę przy brzegu.';const signature=JSON.stringify([!!b,b?.level,b?.passengers.length,b?.combat,a.active,a.islands.map(i=>i.claimed),!!a.fishing]);if(!force&&signature===riverPanelSignature)return;riverPanelSignature=signature;const button=(k,t)=>'<button data-river="'+k+'">'+t+'</button>';$('riverContent').innerHTML='<h3>Wędkowanie</h3><p>Zatrzymaj łódkę. Co 10 sekund gry złowisz 3 żywności. Ruch przerywa łowienie.</p>'+button('fish',a.fishing?'Zwiń wędkę':'Zarzuć wędkę')+'<h3>Ulepszenia i pasażerowie</h3><p>Przy brzegu: poziom 2 kosztuje 30 drewna i 20 monet, poziom 3 — 60 drewna i 40 monet. Prędkość +25% / +50%, miejsca dla 2 / 4 żołnierzy. Załaduj piechurów z odległości do 3 pól. Wyładuj przy brzegu.</p>'+button('upgrade',b?.level>=3?'Maksymalny poziom':'Ulepsz łódkę')+button('repair','Napraw kadłub · 10 drewna')+button('load','Załaduj żołnierzy')+button('unload','Wyładuj żołnierzy')+'<h3>Porty i pomosty</h3><p>Port jest na liście budynków. Pomost kosztuje 10 drewna za pole. Łącz odcinki z brzegiem; możesz po nich chodzić i wysiadać z łódki.</p>'+button('pier','Buduj pomost')+button('port','Buduj port')+'<h3>Wyspy i bitwy</h3><p>Rozpoczęcie tworzy trzy wyspy w bezpiecznych miejscach rzeki oraz trzy wrogie łodzie. Najeźdźcy atakują łódkę i pobliskie porty. Wieże i statki wojenne bronią portów. Po dopłynięciu wysiądź i zbadaj wyspę — każda daje jednorazową nagrodę.</p>'+button('start',a.active?'Wyprawy rozpoczęte':'Rozpocznij wyprawy i bitwy rzeczne')+a.islands.map(i=>'<p>'+i.name+' · '+i.x+', '+i.y+(i.claimed?' · ✓ zbadana':'')+'</p>'+button('locate:'+i.id,'Pokaż kierunek')+button('claim:'+i.id,'Zbadaj wyspę')).join('')+'<h3>Abordaż</h3><p>Włącz ostrzał, aby osłabić wroga do połowy PŻ, potem wyłącz. Z 2 pasażerami podpłyń na 1,6 pola i utrzymaj dystans przez 6 sekund. Potrzebujesz wolnego miejsca na statek w swoim porcie. Zdobyty statek trafia do floty. Zatonięcie oznacza utratę łódki i pasażerów; ludek wraca do domu.</p>'+button('combat',b?.combat?'Wyłącz ostrzał':'Włącz ostrzał łódki')+button('board','Rozpocznij abordaż')}
$('riverContent').onclick=e=>{const el=e.target.closest('[data-river]');if(!el)return;const [action,id]=el.dataset.river.split(':');let ok=true;switch(action){case 'fish':ok=toggleRiverFishing();break;case 'upgrade':ok=upgradeRiverBoat();break;case 'repair':ok=repairRiverBoat();break;case 'load':ok=loadRiverPassengers();break;case 'unload':ok=unloadRiverPassengers();break;case 'pier':setMode('pomost');$('riverPanel').classList.add('hidden');break;case 'port':setMode('port');$('riverPanel').classList.add('hidden');break;case 'start':ok=startRiverAdventure();break;case 'claim':ok=claimRiverIsland(id);break;case 'locate':riverWaypoint(id);break;case 'combat':if(state.playerBoat){state.playerBoat.combat=!state.playerBoat.combat;save()}else ok=false;break;case 'board':ok=beginRiverBoarding();break}if(ok===false)say('Sprawdź warunki opisane w panelu: łódkę, zasoby, brzeg lub odległość.');renderRiver(true)};
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('riverPanel').classList.add('hidden')});riverAdventure();
